// How the project's Reference Docs are organized in the Docs sidebar: a
// strict parent → child tree of categories (and sub-categories) with the
// docs as leaves — base guidelines apart from component specs, engineering
// references and process docs. Docs not placed here (e.g. new ones) fall
// into a category by their type; docs generated by Design System Updates
// get their own branch.

export const DOC_TREE = [
  {
    id: 'guidelines',
    label: 'Guidelines',
    children: [
      { id: 'brand', label: 'Brand', docs: ['doc-brand-guidelines', 'doc-copy'] },
      {
        id: 'foundations',
        label: 'Foundations',
        docs: ['doc-color-tokens', 'doc-type-scale', 'doc-spacing', 'doc-motion', 'doc-iconography', 'doc-dark-mode'],
      },
    ],
  },
  {
    id: 'components',
    label: 'Component specs',
    children: [
      { id: 'inputs', label: 'Actions & inputs', docs: ['doc-button-spec', 'doc-input-spec'] },
      { id: 'containers', label: 'Containers & overlays', docs: ['doc-card-spec', 'doc-modal-spec'] },
      // Written up from Design System Updates (see lib/designSystemUpdates).
      { id: 'ds-updates', label: 'Design system updates', generated: true },
    ],
  },
  {
    id: 'engineering',
    label: 'Engineering',
    docs: ['doc-api-contract', 'doc-api-errors', 'doc-analytics'],
  },
  {
    id: 'process',
    label: 'Process',
    children: [
      { id: 'team', label: 'Team', docs: ['doc-onboarding', 'doc-review', 'doc-handoff'] },
      { id: 'quality', label: 'Quality & release', docs: ['doc-a11y', 'doc-release', 'doc-naming'] },
    ],
  },
]

// Where an unplaced doc goes, by its type.
const FALLBACK = { design: 'foundations', spec: 'inputs', doc: 'team' }

function collectIds(nodes, into = new Set()) {
  for (const node of nodes) {
    node.docs?.forEach((id) => into.add(id))
    if (node.children) collectIds(node.children, into)
  }
  return into
}

// The tree with each node's docs resolved: `{ id, label, docs: [doc],
// children: [...] }`, empty branches dropped.
export function buildDocTree(referenceDocs) {
  const placed = collectIds(DOC_TREE)
  const byId = new Map(referenceDocs.map((d) => [d.id, d]))
  const extras = {}
  for (const doc of referenceDocs) {
    if (placed.has(doc.id)) continue
    const target = doc.dsUpdateId ? 'ds-updates' : (FALLBACK[doc.type] ?? 'team')
    ;(extras[target] ??= []).push(doc)
  }

  function resolve(node) {
    const docs = [...(node.docs ?? []).map((id) => byId.get(id)).filter(Boolean), ...(extras[node.id] ?? [])]
    const children = (node.children ?? []).map(resolve).filter((c) => c.docs.length || c.children.length)
    return { id: node.id, label: node.label, docs, children }
  }

  return DOC_TREE.map(resolve).filter((n) => n.docs.length || n.children.length)
}

// Count of docs under a node, sub-categories included.
export function countDocs(node) {
  return node.docs.length + node.children.reduce((sum, c) => sum + countDocs(c), 0)
}

// The category path to a doc, e.g. ['Guidelines', 'Foundations'].
export function docPath(tree, docId, trail = []) {
  for (const node of tree) {
    const here = [...trail, node.label]
    if (node.docs.some((d) => d.id === docId)) return here
    const found = docPath(node.children, docId, here)
    if (found) return found
  }
  return null
}
